import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { FaBrain, FaExclamationTriangle, FaChartLine, FaHeartbeat } from 'react-icons/fa';

function Burnout() {
  const navigate = useNavigate();
  const [assessment, setAssessment] = useState({
    exhaustion: '',
    cynicism: '',
    efficiency: '',
    stressLevel: ''
  });
  const [result, setResult] = useState(null);
  const [showResult, setShowResult] = useState(false);

  const handleChange = (field, value) => {
    setAssessment({ ...assessment, [field]: value });
  };

  const calculateBurnout = () => {
    let score = 0;
    
    // Exhaustion: High=3, Medium=2, Low=1
    if (assessment.exhaustion === 'high') score += 3;
    if (assessment.exhaustion === 'medium') score += 2;
    if (assessment.exhaustion === 'low') score += 1;
    
    // Cynicism: High=3, Medium=2, Low=1
    if (assessment.cynicism === 'high') score += 3;
    if (assessment.cynicism === 'medium') score += 2;
    if (assessment.cynicism === 'low') score += 1;
    
    // Efficiency: LOW = 3 points (bad), MEDIUM = 2, HIGH = 1 (good)
    if (assessment.efficiency === 'low') score += 3;
    if (assessment.efficiency === 'medium') score += 2;
    if (assessment.efficiency === 'high') score += 1;
    
    // Stress Level: High=3, Medium=2, Low=1
    if (assessment.stressLevel === 'high') score += 3;
    if (assessment.stressLevel === 'medium') score += 2;
    if (assessment.stressLevel === 'low') score += 1;
    
    let level = '';
    let advice = '';
    let color = '';
    
    if (score <= 6) {
      level = 'Low Risk';
      advice = 'You\'re doing well! Keep maintaining healthy habits.';
      color = '#2ecc71';
    } else if (score <= 10) {
      level = 'Moderate Risk';
      advice = 'Early signs of burnout. Take time to recharge.';
      color = '#f39c12';
    } else {
      level = 'High Risk';
      advice = 'You may be experiencing burnout. Consider talking to a counselor.';
      color = '#e74c3c';
    }
    
    setResult({ score, level, advice, color });
    setShowResult(true);
  };

  const resetAssessment = () => {
    setAssessment({ exhaustion: '', cynicism: '', efficiency: '', stressLevel: '' });
    setShowResult(false);
    setResult(null);
  };

  const options = [
    { value: 'low', label: 'Low', color: '#2ecc71' },
    { value: 'medium', label: 'Medium', color: '#f39c12' },
    { value: 'high', label: 'High', color: '#e74c3c' }
  ];

  // Efficiency options (reversed meaning - Low efficiency is bad)
  const efficiencyOptions = [
    { value: 'high', label: 'High', color: '#2ecc71' },
    { value: 'medium', label: 'Medium', color: '#f39c12' },
    { value: 'low', label: 'Low', color: '#e74c3c' }
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>🔥 Academic Burnout Check</h1>
          <p style={styles.subtitle}>Quick assessment - 2 minutes</p>
        </div>

        <div style={styles.card}>
          {!showResult ? (
            <>
              {/* Question 1 - Exhaustion */}
              <div style={styles.questionSection}>
                <div style={styles.questionHeader}>
                  <span style={styles.questionNum}>1</span>
                  <span style={styles.questionText}>How often do you feel emotionally exhausted after studying?</span>
                </div>
                <div style={styles.optionsRow}>
                  {options.map(opt => (
                    <button
                      key={opt.value}
                      onClick={() => handleChange('exhaustion', opt.value)}
                      style={{...styles.optionBtn, background: assessment.exhaustion === opt.value ? opt.color : '#f0f0f0', color: assessment.exhaustion === opt.value ? 'white' : '#555'}}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Question 2 - Cynicism */}
              <div style={styles.questionSection}>
                <div style={styles.questionHeader}>
                  <span style={styles.questionNum}>2</span>
                  <span style={styles.questionText}>Do you feel cynical or detached from your studies?</span>
                </div>
                <div style={styles.optionsRow}>
                  {options.map(opt => (
                    <button
                      key={opt.value}
                      onClick={() => handleChange('cynicism', opt.value)}
                      style={{...styles.optionBtn, background: assessment.cynicism === opt.value ? opt.color : '#f0f0f0', color: assessment.cynicism === opt.value ? 'white' : '#555'}}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Question 3 - Efficiency (Corrected) */}
              <div style={styles.questionSection}>
                <div style={styles.questionHeader}>
                  <span style={styles.questionNum}>3</span>
                  <span style={styles.questionText}>How would you rate your academic efficiency?</span>
                </div>
                <div style={styles.optionsRow}>
                  {efficiencyOptions.map(opt => (
                    <button
                      key={opt.value}
                      onClick={() => handleChange('efficiency', opt.value)}
                      style={{...styles.optionBtn, background: assessment.efficiency === opt.value ? opt.color : '#f0f0f0', color: assessment.efficiency === opt.value ? 'white' : '#555'}}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Question 4 - Stress Level */}
              <div style={styles.questionSection}>
                <div style={styles.questionHeader}>
                  <span style={styles.questionNum}>4</span>
                  <span style={styles.questionText}>What is your current stress level?</span>
                </div>
                <div style={styles.optionsRow}>
                  {options.map(opt => (
                    <button
                      key={opt.value}
                      onClick={() => handleChange('stressLevel', opt.value)}
                      style={{...styles.optionBtn, background: assessment.stressLevel === opt.value ? opt.color : '#f0f0f0', color: assessment.stressLevel === opt.value ? 'white' : '#555'}}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              <button onClick={calculateBurnout} style={styles.assessBtn}>
                See My Result →
              </button>
            </>
          ) : (
            <div style={styles.resultContainer}>
              <div style={{...styles.resultCard, borderTop: `4px solid ${result.color}`}}>
                <div style={styles.resultScore}>
                  <span style={{fontSize: '36px', fontWeight: 'bold', color: result.color}}>{result.score}</span>
                  <span>/12</span>
                </div>
                <div style={{...styles.resultLevel, background: `${result.color}15`, color: result.color}}>
                  {result.level}
                </div>
                <p style={styles.resultAdvice}>{result.advice}</p>
                {result.level === 'High Risk' && (
                  <div style={styles.emergencyTip}>
                    <FaHeartbeat /> Consider reaching out for support.
                  </div>
                )}
              </div>
              <button onClick={resetAssessment} style={styles.resetBtn}>
                Take Again
              </button>
            </div>
          )}
        </div>

        <div style={styles.tipsCard}>
          <span style={styles.tipsIcon}>💡</span>
          <span style={styles.tipsText}>Take breaks • Sleep well • Stay hydrated</span>
        </div>
      </div>
    </div>
  );
}

